import{_ as n,I as t,o as r,c as d,b6 as i,j as o,J as e,w as p}from"./chunks/framework.COUcLbTA.js";const _=JSON.parse('{"title":"现代 AI 生图 SaaS 开发实战","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/stage-2/assignments/modern-landing-page/index.md","filePath":"zh-cn/stage-2/assignments/modern-landing-page/index.md"}'),h={name:"zh-cn/stage-2/assignments/modern-landing-page/index.md"},c={style:{margin:"32px 0"}};function b(g,a,k,u,m,f){const l=t("StepBar"),s=t("ClientOnly");return r(),d("div",null,[a[0]||(a[0]=i('<h1 id="现代-ai-生图-saas-开发实战" tabindex="-1">现代 AI 生图 SaaS 开发实战 <a class="header-anchor" href="#现代-ai-生图-saas-开发实战" aria-label="Permalink to “现代 AI 生图 SaaS 开发实战”">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to “概述”">​</a></h2><p>本实战项目要求你围绕一份真实的 PRD（产品需求文档），从零完成一个参考 Midjourney 体验的 AI 生图 SaaS 产品。你将完整经历需求分析、项目拆解、迭代开发、联调上线的全过程。</p><p>这是 Stage 2 的综合实战环节。在前面几章中，你已经分别学习了前端页面设计、后端接口开发、数据库操作、支付集成等单项技能——这个项目要求你把它们全部串起来，交付一个可运行的产品原型。</p><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to “前置知识”">​</a></h2><p>在开始本项目之前，你应该已经掌握以下内容：</p><ul><li>前端页面设计与组件库使用（<a href="./../../frontend/ui-design/">UI 设计</a>、<a href="./../../frontend/modern-component-library/">现代组件库</a>）</li><li>后端接口设计与开发（<a href="./../../backend/ai-interface-code/">接口代码编写</a>）</li><li>数据库基础与 Supabase（<a href="./../../backend/database-supabase/">从数据库到 Supabase</a>）</li><li>支付集成（<a href="./../../backend/stripe-payment/">Stripe 收费系统</a>）</li><li>Git 工作流与部署（<a href="./../../backend/git-workflow/">Git 和 GitHub</a>、<a href="./../../backend/zeabur-deployment/">部署 Web 应用</a>）</li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to “学习目标”">​</a></h2><p>完成本实战后，你将能够：</p><ol><li>阅读并理解一份真实的 PRD，从中提取开发任务清单</li><li>基于 PRD 拆分模块，制定分步推进计划</li><li>使用 AI 辅助完成前端骨架搭建和后端接口开发</li><li>对每个模块进行验证和迭代优化</li><li>完成端到端联调，将项目从&quot;能跑&quot;推进到&quot;能交付&quot;</li></ol><h2 id="项目简介" tabindex="-1">项目简介 <a class="header-anchor" href="#项目简介" aria-label="Permalink to “项目简介”">​</a></h2><p>你要构建的产品是一个现代 AI 生图 SaaS 平台，包含三个子系统：</p><table tabindex="0"><thead><tr><th>子系统</th><th>职责</th></tr></thead><tbody><tr><td><strong>官网前台</strong></td><td>产品介绍、定价、FAQ、注册转化</td></tr><tr><td><strong>用户工作台</strong></td><td>Prompt 输入、图片生成、图库、积分、套餐、社区互动</td></tr><tr><td><strong>后台管理台</strong></td><td>用户管理、任务管理、支付管理、内容审核、SaaS 指标、系统监控</td></tr></tbody></table><p>后端需要支持以下核心能力：用户鉴权、图片生成任务、OSS 对象存储、积分与套餐支付、图片社交互动、运营数据监控。</p><div class="tip custom-block"><p class="custom-block-title">PRD 入口</p><p>本项目的需求文档在 GitHub： <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/zh-cn/stage-2/assignments/modern-landing-page/PRD.md" target="_blank" rel="noreferrer">查看 PRD</a></p></div>',15)),o("div",c,[e(s,null,{default:p(()=>[e(l,{active:0,items:[{title:"需求分析",description:"阅读 PRD，提取页面、模块、数据模型和边界"},{title:"搭建骨架",description:"用 AI 生成三套前端骨架（www / app / admin）"},{title:"迭代开发",description:"逐模块补充接口、权限、支付、监控"},{title:"联调上线",description:"端到端跑通，部署并准备演示"}]})]),_:1})]),a[1]||(a[1]=i(`<h2 id="第一部分-需求分析" tabindex="-1">第一部分：需求分析 <a class="header-anchor" href="#第一部分-需求分析" aria-label="Permalink to “第一部分：需求分析”">​</a></h2><h3 id="_1-1-阅读-prd" tabindex="-1">1.1 阅读 PRD <a class="header-anchor" href="#_1-1-阅读-prd" aria-label="Permalink to “1.1 阅读 PRD”">​</a></h3><p>打开 PRD 文档，重点回答以下问题：</p><ul><li>系统有几个入口？各自覆盖哪些页面？</li><li>每个页面的核心功能是什么？</li><li>后端包含哪些模块和数据库表？</li><li>MVP 范围是什么？第一版哪些做，哪些不做？</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>如果以上问题没有明确答案，不要开始写代码。需求理解不清楚是导致返工的最常见原因。</p></div><h3 id="_1-2-确认系统架构" tabindex="-1">1.2 确认系统架构 <a class="header-anchor" href="#_1-2-确认系统架构" aria-label="Permalink to “1.2 确认系统架构”">​</a></h3><p>根据 PRD 中的描述，梳理出系统的整体架构：</p><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; web[&quot;官网前台&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; app[&quot;用户工作台&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; admin[&quot;后台管理台&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; auth[&quot;鉴权&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; gen[&quot;图片生成任务&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gen --&gt; oss[&quot;OSS 对象存储&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gen --&gt; db[&quot;数据库&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  billing[&quot;支付与套餐&quot;] --&gt; db</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  social[&quot;分享 / 点赞 / 评论 / 转发&quot;] --&gt; db</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; analytics[&quot;SaaS 指标看板&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; observability[&quot;API / DB / Provider 监控&quot;]</span></span></code></pre></div><p>建议你用自己的话把架构图画一遍，确认你对系统的理解是完整的。</p><h2 id="第二部分-搭建项目骨架" tabindex="-1">第二部分：搭建项目骨架 <a class="header-anchor" href="#第二部分-搭建项目骨架" aria-label="Permalink to “第二部分：搭建项目骨架”">​</a></h2><h3 id="_2-1-生成前端页面" tabindex="-1">2.1 生成前端页面 <a class="header-anchor" href="#_2-1-生成前端页面" aria-label="Permalink to “2.1 生成前端页面”">​</a></h3><p>使用 AI 先生成所有页面的基本结构和假数据。这一步的目标是搭出信息架构和路由，不需要接真实接口。</p><p>提示词参考：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请基于当前 PRD，帮我生成一个现代 AI 生图 SaaS 的前端骨架。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>1. 分成三个入口：www、app、admin</span></span>
<span class="line"><span>2. 官网包括：首页、定价、FAQ</span></span>
<span class="line"><span>3. app 包括：登录、注册、生成工作台、图库、套餐、积分、社区、作品详情、个人中心</span></span>
<span class="line"><span>4. admin 包括：后台首页、用户管理、任务管理、内容管理、套餐管理、支付订单、运营配置、SaaS 指标、系统监控</span></span>
<span class="line"><span>5. 先只生成页面结构和假数据，不接真实接口</span></span>
<span class="line"><span>6. 风格参考 Midjourney，简洁、现代、带产品感</span></span></code></pre></div><h3 id="_2-2-验证页面结构" tabindex="-1">2.2 验证页面结构 <a class="header-anchor" href="#_2-2-验证页面结构" aria-label="Permalink to “2.2 验证页面结构”">​</a></h3><p>骨架生成后，逐项检查：</p><ul><li>[ ] 三个入口的路由是否独立（<code>/</code>、<code>/app</code>、<code>/admin</code>）</li><li>[ ] 页面数量是否与 PRD 一致</li><li>[ ] 每个页面是否可以正常访问和导航</li><li>[ ] 假数据是否展示了基本的 UI 状态（列表、空状态、表单等）</li></ul><h2 id="第三部分-迭代开发" tabindex="-1">第三部分：迭代开发 <a class="header-anchor" href="#第三部分-迭代开发" aria-label="Permalink to “第三部分：迭代开发”">​</a></h2><h3 id="_3-1-按模块推进" tabindex="-1">3.1 按模块推进 <a class="header-anchor" href="#_3-1-按模块推进" aria-label="Permalink to “3.1 按模块推进”">​</a></h3><p>在骨架的基础上，按以下顺序逐模块补充功能：</p><ol><li><strong>鉴权</strong>：注册、登录、角色区分</li><li><strong>数据库</strong>：数据表创建、读写接口</li><li><strong>核心业务</strong>：图片生成任务、结果存储</li><li><strong>OSS 存储</strong>：图片上传与访问</li><li><strong>支付</strong>：套餐、积分、Stripe 集成</li><li><strong>社交互动</strong>：分享、点赞、评论</li><li><strong>后台管理</strong>：用户管理、任务管理、内容审核</li><li><strong>数据监控</strong>：SaaS 指标看板、系统监控</li></ol><p>每完成一个模块，使用下表进行自检：</p><table tabindex="0"><thead><tr><th>检查项</th><th>验证方法</th></tr></thead><tbody><tr><td>页面一致性</td><td>页面数量、入口、功能是否符合 PRD</td></tr><tr><td>接口正确性</td><td>请求参数、返回结构、状态处理是否合理</td></tr><tr><td>权限隔离</td><td>普通用户和管理员是否互相隔离</td></tr><tr><td>数据一致性</td><td>数据库、OSS、支付、积分是否对得上</td></tr><tr><td>可演示性</td><td>是否能给别人完整演示一条业务链路</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>如果发现 AI 生成的内容偏离了 PRD，不要整页推翻重来，直接让它修改具体模块即可。</p></div><h3 id="_3-2-角色与分工" tabindex="-1">3.2 角色与分工 <a class="header-anchor" href="#_3-2-角色与分工" aria-label="Permalink to “3.2 角色与分工”">​</a></h3><p>在迭代过程中，你需要同时扮演三个角色：</p><ul><li><strong>产品经理</strong>：确认每个模块的功能是否符合 PRD</li><li><strong>技术负责人</strong>：确认实现方案是否合理</li><li><strong>测试工程师</strong>：确认功能是否跑得通</li></ul><h2 id="第四部分-联调与上线" tabindex="-1">第四部分：联调与上线 <a class="header-anchor" href="#第四部分-联调与上线" aria-label="Permalink to “第四部分：联调与上线”">​</a></h2><h3 id="_4-1-端到端测试" tabindex="-1">4.1 端到端测试 <a class="header-anchor" href="#_4-1-端到端测试" aria-label="Permalink to “4.1 端到端测试”">​</a></h3><p>最后阶段的重点不是补新页面，而是把完整业务链路跑通。至少验证以下场景：</p><ul><li>注册 → 购买积分 → 生成图片 → 查看历史 → 分享互动</li><li>管理员登录 → 查看用户数据 → 查看任务统计 → 查看系统监控</li></ul><h3 id="_4-2-部署" tabindex="-1">4.2 部署 <a class="header-anchor" href="#_4-2-部署" aria-label="Permalink to “4.2 部署”">​</a></h3><p>将项目部署到公网环境，确保：</p><ul><li>环境变量配置完整</li><li>登录回调地址正确</li><li>支付回调地址正确</li><li>页面无缺失的 loading、空状态、错误提示</li></ul><p>部署教程参考：<a href="./../../backend/git-workflow/">Git 和 GitHub 工作流</a>、<a href="./../../backend/zeabur-deployment/">如何部署 Web 应用</a>。</p><h2 id="交付物" tabindex="-1">交付物 <a class="header-anchor" href="#交付物" aria-label="Permalink to “交付物”">​</a></h2><p>完成本项目后，你需要提交以下内容：</p><ul><li>[ ] 可访问的线上演示链接</li><li>[ ] 源码仓库链接（含 README）</li><li>[ ] PRD 文档</li><li>[ ] 核心页面截图（官网首页、生图工作台、图库、套餐页、后台首页）</li><li>[ ] 60 秒演示视频（覆盖注册 → 生成 → 查看 → 后台管理）</li></ul><p>README 至少包含：项目简介、核心页面说明、技术栈、本地启动步骤、环境变量清单。</p><h2 id="评分标准" tabindex="-1">评分标准 <a class="header-anchor" href="#评分标准" aria-label="Permalink to “评分标准”">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>基本要求</th><th>进阶要求</th></tr></thead><tbody><tr><td>PRD 对齐</td><td>页面、功能、数据结构基本符合 PRD</td><td>能清晰说明每个设计决策与 PRD 的对应关系</td></tr><tr><td>产品闭环</td><td>注册 → 购买积分 → 生成图片 → 查看历史 → 分享互动可跑通</td><td>支付状态、积分余额、生成次数数据一致</td></tr><tr><td>后台能力</td><td>用户、任务、支付、内容管理可查看</td><td>SaaS 指标看板和系统监控页完整可用</td></tr><tr><td>工程完整度</td><td>前端、后端、数据库、OSS、支付链路已接通</td><td>有错误处理、空状态、loading 状态</td></tr><tr><td>交付质量</td><td>可部署、可运行</td><td>README 清楚、演示视频结构完整</td></tr></tbody></table><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to “参考资料”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">UI 设计</a></li><li><a href="./../../frontend/multi-product-ui/">参考 UI 设计规范设计页面和按钮</a></li><li><a href="./../../frontend/llm-skills-beautiful/">用 LLM 和 Skills 让界面变好看</a></li><li><a href="./../../frontend/design-to-code/">从设计原型到项目代码</a></li><li><a href="./../../frontend/modern-component-library/">使用现代组件库更新你的界面</a></li><li><a href="./../../backend/database-supabase/">从数据库到 Supabase</a></li><li><a href="./../../backend/ai-interface-code/">大模型辅助编写接口代码与接口文档</a></li><li><a href="./../../backend/git-workflow/">Git 和 GitHub 工作流</a></li><li><a href="./../../backend/zeabur-deployment/">如何部署 Web 应用</a></li><li><a href="./../../backend/stripe-payment/">如何集成 Stripe 等收费系统</a></li></ul>`,43))])}const P=n(h,[["render",b]]);export{_ as __pageData,P as default};
